import {ASSESSMENTS,SUBJECTS,CORE,clean,subjectCode,grade,yearNumber,parseJson,validateRecords,mergeRows,viewData,recordKey,exportCsv,selectRows} from './core.mjs';
import {parseMptPdf} from './pdf.mjs';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
let apiUrl=window.SAP_CONFIG?.apiUrl||localStorage.getItem('sap.v3.api')||'';
let state={config:{sessions:[{year:'2026',locked:false}],activeSession:'2026',assessments:ASSESSMENTS},records:[],version:'',demo:true};
let page='home',people=[],currentSubjects=[],search='',admin=null,teacher=null,pending=null,originalOnline=null;
let f={session:'2026',assessment:'COMBINED',assessments:['COMBINED'],year:'',className:'',subject:'',tp:'',sort:'rank'};
const sheet=$('#sheet');let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function status(s,warn=false){$('#connection').textContent=s;$('#connection').classList.toggle('warn',warn);}
function modal(title,html){$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=html;if(!sheet.open)sheet.showModal();}
$('#close-sheet').onclick=()=>sheet.close();sheet.addEventListener('click',e=>{if(e.target===sheet)sheet.close();});
async function request(action,body){if(!apiUrl)throw Error('URL Apps Script v3 belum ditetapkan.');const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);try{const res=await fetch(body?apiUrl:`${apiUrl}${apiUrl.includes('?')?'&':'?'}action=${action}`,body?{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,...body}),signal:controller.signal}:{signal:controller.signal,cache:'no-store'});if(!res.ok)throw Error('Sambungan pelayan gagal ('+res.status+').');const data=await res.json();if(!data.ok)throw Error(data.error||'Permintaan gagal.');return data;}catch(e){if(e.name==='AbortError')throw Error('Pelayan mengambil masa terlalu lama. Data terakhir masih boleh digunakan.');throw e;}finally{clearTimeout(timeout);}}
async function cached(value){try{const db=await new Promise((resolve,reject)=>{const q=indexedDB.open('sap-temin-v3',1);q.onupgradeneeded=()=>q.result.createObjectStore('cache');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});try{return await new Promise((resolve,reject)=>{const tx=db.transaction('cache',value?'readwrite':'readonly');const store=tx.objectStore('cache');const q=value?store.put(value,apiUrl):store.get(apiUrl);q.onsuccess=()=>{if(!value)resolve(q.result);};tx.oncomplete=()=>{if(value)resolve(value);};tx.onerror=()=>reject(tx.error);});}finally{db.close();}}catch(e){return null;}}
function demoData(){const rows=[];const names=['MURID CONTOH A','MURID CONTOH B','MURID CONTOH C','MURID CONTOH D','MURID CONTOH E','MURID CONTOH F','MURID CONTOH G','MURID CONTOH H'];for(let y=4;y<=6;y++)for(let i=0;i<8;i++){const key=String(y*100+i).padStart(64,'0');for(let j=0;j<8;j++){const sub=['BM','BI','MT','SN','PI','BA','RBT','SEJ'][j];const mark=Math.min(100,35+((i*13+j*9+y*7)%63));const common={session:'2026',year:y,className:i<4?'DELTA':'GAMMA',studentKey:key,name:names[i],gender:i%2?'P':'L',subject:sub};rows.push({...common,type:'MARKAH',assessment:y===4&&CORE.includes(sub)?'MPT4':'UASA',mark,grade:grade(mark),tp:null,status:'OK',source:y===4&&CORE.includes(sub)?'MPT4':'UASA'});rows.push({...common,type:'TP',assessment:'PBD_END',mark:null,grade:null,tp:'TP'+(i===7&&j<2?2:Math.min(6,3+(i+j)%4)),status:'OK',source:'PBD Akhir',effort:'TINGGI',comment:'Contoh ulasan guru. Ini bukan data murid sebenar.'});rows.push({...common,type:'TP',assessment:'PBD_MID',mark:null,grade:null,tp:'TP'+(i===7&&j<2?2:Math.min(5,3+(i+j)%3)),status:'OK',source:'PBD Pertengahan'});}}return rows;}
function setData(d){const firstLoad=state.demo||!state.version;state=d;f.session=d.config.activeSession||f.session;if(firstLoad&&selectedAssessments().length===1&&f.assessment==='COMBINED'&&!d.records.some(r=>String(r.session)===f.session&&['UASA','MPT4','PBD_END'].includes(r.assessment))&&d.records.some(r=>String(r.session)===f.session&&r.assessment==='PBD_MID')){f.assessment='PBD_MID';f.assessments=['PBD_MID'];}initFilters();render();}
async function sync(force=false){if(!apiUrl){status('MOD CONTOH · Data rekaan untuk mencuba menu. Sambungan Google Sheets belum diaktifkan.',true);return;}try{if(state.version&&!state.demo&&!force){status('Salinan peranti tersedia · menyemak kemas kini…');const manifest=await request('manifest_v3');if(manifest.apiVersion!=='3.0.0')throw Error('Endpoint ini belum menggunakan Apps Script v3.');if(state.version===manifest.version){status('Data terkini · '+formatDate(state.version));return;}}status(state.version?'Memuatkan kemas kini data pusat…':'Memuatkan data pusat kali pertama…');const d=await request('dataset_v3');if(d.apiVersion!=='3.0.0'||!Array.isArray(d.records))throw Error('Data pusat tidak menggunakan format v3 yang sah.');setData({...d,demo:false});await cached({...d,demo:false});status('Data pusat · dikemas kini '+formatDate(d.version));}catch(e){status(e.message+' Paparan terakhir dikekalkan.',true);toast(e.message);}}
function formatDate(d){return d?new Date(d).toLocaleString('ms-MY',{timeZone:'Asia/Kuala_Lumpur',dateStyle:'medium',timeStyle:'short'}):'—';}
const option=(v,label,selected)=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(label)}</option>`;
function initFilters(){const sessions=state.config.sessions;$('#f-session').innerHTML=sessions.map(s=>option(s.year,s.year+(s.locked?' · Arkib':''),f.session)).join('');renderAssessmentPicker();rebuildFilters();}
function rebuildFilters(){const sessionRows=state.records.filter(r=>String(r.session)===f.session);const years=[...new Set(sessionRows.map(r=>r.year))].sort();if(f.assessment==='MPT4')f.year='4';$('#f-year').innerHTML=option('','Semua tahun',f.year)+years.map(y=>option(y,'Tahun '+y,f.year)).join('');$('#f-year').value=f.year;$('#f-year').disabled=f.assessment==='MPT4';const classes=[...new Set(sessionRows.filter(r=>!f.year||r.year===Number(f.year)).map(r=>r.className))].sort();if(f.className&&!classes.includes(f.className))f.className='';$('#f-class').innerHTML=option('','Semua kelas',f.className)+classes.map(c=>option(c,c,f.className)).join('');const subjects=[...new Set(sessionRows.filter(r=>(!f.year||r.year===Number(f.year))&&selectedAssessments().some(id=>id==='COMBINED'?['UASA','MPT4','PBD_END'].includes(r.assessment):r.assessment===id)).map(r=>r.subject))].sort((a,b)=>Object.keys(SUBJECTS).indexOf(a)-Object.keys(SUBJECTS).indexOf(b));if(f.subject&&!subjects.includes(f.subject))f.subject='';$('#f-subject').innerHTML=option('','Semua subjek',f.subject)+subjects.map(s=>option(s,SUBJECTS[s]||s,f.subject)).join('');$('#f-sort').value=f.sort;}
for(const [id,key]of [['session','session'],['year','year'],['class','className'],['subject','subject'],['sort','sort']])$('#f-'+id).onchange=e=>{f[key]=e.target.value;if(key==='session'||key==='assessment'){f.className='';f.subject='';if(key==='assessment'&&f.assessment!=='MPT4')f.year='';}if(key==='sort'&&f.sort==='subject'&&!f.subject){toast('Pilih satu subjek untuk susunan markah tertinggi.');f.sort='rank';}rebuildFilters();render();};
$('#reset-filters').onclick=()=>{f={session:state.config.activeSession||'2026',assessment:'COMBINED',assessments:['COMBINED'],year:'',className:'',subject:'',tp:'',sort:'rank'};initFilters();render();};
function go(p){page=p;search='';sheet.close();$('#filters-box').hidden=['admin','settings','dialog','help','reports'].includes(p);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render();window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
$('#more').onclick=()=>modal('Lagi',`<div class="sheet-grid">${quick('reports','file','Pusat laporan','Cetak dan eksport keputusan')}${quick('dialog','chart','Dialog prestasi','Analisis dan pelan tindakan')}${quick('preview','upload','Pratonton fail','Semak JSON/PDF pada peranti')}${quick('settings','more','Sambungan','Tetapkan URL Apps Script')}${quick('help','file','Panduan','Cara guna SAP-TEMIN')}${admin?quick('admin','upload','Admin','Upload dan pengurusan sesi'):''}</div><p class="hint">SAP-TEMIN · versi 3.0 · ${esc(f.session)}</p>`);
function quick(p,i,title,desc){return `<button class="quick" data-go="${p}">${icon(i)}<span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}
let taps=[];$('#brand-logo').onclick=()=>{const now=Date.now();taps=taps.filter(t=>now-t<1800);taps.push(now);if(taps.length>=3){taps=[];admin?go('admin'):adminLogin();}};
$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('sap.v3.theme',document.body.classList.contains('dark')?'dark':'light');};if(localStorage.getItem('sap.v3.theme')==='dark')document.body.classList.add('dark');$('#refresh').onclick=()=>sync();
function title(a,b,c){$('#page-title').textContent=a;$('#page-title').hidden=!a;$('#page-description').textContent=b;$('#section-tag').textContent=c||'SAP-TEMIN · '+f.session;}
function pbdOnly(){return selectedAssessments().length>0&&selectedAssessments().every(id=>id==='PBD_MID'||id==='PBD_END')||Boolean(f.year&&Number(f.year)<=3&&selectedAssessments().includes('COMBINED'));}
function render(){people=viewData(state.records,f);currentSubjects=[...new Set(people.flatMap(p=>(p.assessmentViews||[p]).flatMap(v=>[...Object.keys(v.marks),...Object.keys(v.pbd)])))].filter(s=>!f.subject||s===f.subject).sort((a,b)=>Object.keys(SUBJECTS).indexOf(a)-Object.keys(SUBJECTS).indexOf(b));$('#scope-label').textContent=[f.session,f.year?'Tahun '+f.year:'Semua tahun',f.className||'Semua kelas'].join(' · ');const views={home:homeView,analysis:analysisView,students:studentsView,intervention:interventionView,reports:reportsView,dialog:dialogView,settings:settingsView,help:helpView,admin:adminView};(views[page]||homeView)();}
function printTitle(){return `<div class="print-title"><h2>SAP-TEMIN · SK TEMIN</h2><p>${esc(assessmentName())} · ${esc($('#scope-label').textContent)}${f.subject?' · '+esc(SUBJECTS[f.subject]||f.subject):''}</p></div>`;}
function assessmentLabel(id){return id==='COMBINED'?'UASA + MPT4 · bersama PBD Akhir':state.config.assessments.find(a=>a.id===id)?.name||id;}
function selectedAssessments(){return f.assessments||[f.assessment];}
function assessmentName(){return selectedAssessments().map(assessmentLabel).join(' + ')||'Tiada pentaksiran dipilih';}
function renderAssessmentPicker(){const ids=selectedAssessments();$('#assessment-summary').textContent=assessmentName();$('#f-assessment').innerHTML=[{id:'COMBINED'},...state.config.assessments].map(a=>`<label><input type="checkbox" value="${esc(a.id)}" ${ids.includes(a.id)?'checked':''}><span>${esc(assessmentLabel(a.id))}</span></label>`).join('');}
// Close the assessment menu on outside mouse/touch input or Escape.
document.addEventListener('pointerdown',e=>{const picker=$('#assessment-picker');if(picker.open&&!picker.contains(e.target))picker.open=false;});
document.addEventListener('keydown',e=>{const picker=$('#assessment-picker');if(e.key==='Escape'&&picker.open){picker.open=false;picker.querySelector('summary').focus();}});
$('#f-assessment').onchange=e=>{const id=e.target.value;let ids=selectedAssessments().filter(x=>x!==id);if(e.target.checked){if(id==='COMBINED')ids=ids.filter(x=>!['UASA','MPT4','PBD_END'].includes(x));else if(['UASA','MPT4','PBD_END'].includes(id))ids=ids.filter(x=>x!=='COMBINED');ids.push(id);}f.assessments=ids;f.assessment=ids.length===1?ids[0]:'MULTI';renderAssessmentPicker();rebuildFilters();render();};
function metrics(){const marks=people.flatMap(p=>Object.values(p.marks)).filter(r=>(!f.subject||r.subject===f.subject)&&r.status==='OK'&&r.mark!==null);const tp=people.flatMap(p=>Object.values(p.pbd)).filter(r=>(!f.subject||r.subject===f.subject)&&/^TP[1-6]$/.test(r.tp));const avg=marks.length?marks.reduce((s,r)=>s+r.mark,0)/marks.length:null;const mastery=tp.length?100*tp.filter(r=>Number(r.tp.slice(2))>=3).length/tp.length:null;return {marks,tp,avg,mastery,focus:people.filter(p=>Object.values(p.pbd).some(r=>(!f.subject||r.subject===f.subject)&&/^TP[12]$/.test(r.tp))).length};}
function kpi(label,value,note,green=false){return `<article class="kpi ${green?'green':''}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;}
function homeView(){title('','SK TEMIN · ANALISIS AKADEMIK','PUSAT ANALISIS SEKOLAH');const m=metrics();$('#view').innerHTML=`${printTitle()}<section class="panel hero"><div><small>${esc(assessmentName())} · SESI ${esc(f.session)}</small><h2>Data jelas. Tindakan lebih terarah.</h2><p>Lihat pencapaian murid, bandingkan penguasaan dan rancang bimbingan melalui satu paparan.</p></div><button class="btn" data-go="students">Lihat keputusan murid</button></section><div class="kpi-grid">${kpi('Murid dalam paparan',people.length,'Murid unik, bukan bilangan rekod')}${kpi('Purata markah',m.avg===null?'—':m.avg.toFixed(1)+'%','Rekod yang mempunyai markah')}${kpi('PBD TP3–TP6',m.mastery===null?'—':m.mastery.toFixed(1)+'%','Daripada rekod TP yang ditaksir',true)}${kpi('Fokus bimbingan',m.focus,'Murid mempunyai TP1 / TP2')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h3>Taburan penguasaan PBD</h3><p>Tekan tahap untuk melihat senarai murid.</p></div><span class="badge">${m.tp.length} rekod</span></div>${tpBars(m.tp)}</section><section class="panel"><div class="panel-head"><div><h3>Markah mengikut subjek</h3><p>Purata rekod yang ditaksir sahaja.</p></div></div>${subjectBars(m.marks)}</section></div><div class="quick-grid">${quick('analysis','chart','Teroka analisis','Tahun, kelas dan subjek')}${quick('intervention','target','Bimbingan berfokus','Murid dan tindakan susulan')}${quick('reports','file','Laporan sedia cetak','Keputusan dan ringkasan')}</div>${state.demo?'<div class="notice warn">Data contoh rekaan. Gunakan Lagi → Pratonton fail untuk mencuba fail sendiri, atau tetapkan sambungan selepas pemasangan Apps Script v3.</div>':''}`;}
function tpBars(rows){return [1,2,3,4,5,6].map(n=>{const count=rows.filter(r=>r.tp==='TP'+n).length;return `<div class="bar-row"><button data-tp="TP${n}">TP${n}</button><div class="bar-track"><div class="bar-fill" style="width:${rows.length?count/rows.length*100:0}%;background:${n<3?'#c76a58':['','','','#80bdb1','#48a995','#168c80','#086f73'][n]}"></div></div><small>${count} · ${rows.length?(count/rows.length*100).toFixed(0):0}%</small></div>`;}).join('');}
function subjectBars(rows){const subs=[...new Set(rows.map(r=>r.subject))];return subs.map(s=>{const v=rows.filter(r=>r.subject===s);const avg=v.reduce((a,r)=>a+r.mark,0)/v.length;return `<div class="bar-row"><button data-subject="${esc(s)}">${esc(s)}</button><div class="bar-track"><div class="bar-fill" style="width:${avg}%"></div></div><small>${avg.toFixed(1)}%</small></div>`;}).join('')||'<p class="hint">Tiada markah dalam pilihan ini.</p>';}
function toolbar(){return `<div class="actions"><button class="btn secondary" data-action="csv">Muat turun CSV</button><button class="btn secondary" data-action="print">Cetak / PDF</button><span class="badge">${people.length} murid</span></div>`;}
function resultsTable(list=people){if(list.some(p=>p.assessmentViews))return multiResultsTable(list);if(!list.length)return '<div class="empty"><h2>Tiada keputusan dalam pilihan ini.</h2><p>Tukar sesi, pentaksiran atau penapis.</p></div>';return `<div class="table-scroll"><table class="results-table"><thead><tr><th class="rank">${f.sort==='subject'?'Kedudukan subjek':'Kedudukan'}</th><th class="name">Nama murid / Kelas</th><th>Pentaksiran</th>${currentSubjects.map(s=>`<th title="${esc(SUBJECTS[s]||s)}">${esc(s)}</th>`).join('')}<th>Bil. A</th><th>Jumlah</th><th>Purata</th></tr></thead>${list.map(p=>{const hasMarks=Object.keys(p.marks).length;const hasPbd=Object.keys(p.pbd).length;const name=`<td class="name" ${hasMarks&&hasPbd?'rowspan="2"':''}><button data-profile="${esc(p.key)}">${esc(p.name)}</button><small>${p.year} ${esc(p.className)}</small>${hasMarks&&!p.complete?'<span class="badge warn">Belum lengkap</span>':''}</td>`;const rank=`<td class="rank" ${hasMarks&&hasPbd?'rowspan="2"':''}>${hasMarks?((f.sort==='subject'?p.subjectRank:p.rank)||'—'):'—'}</td>`;let html='';if(hasMarks)html=`<tr class="uasa-row">${rank}${name}<td>${f.assessment==='COMBINED'?(p.year===4?'UASA + MPT4':'UASA'):esc(assessmentLabel(f.assessment))}</td>${currentSubjects.map(s=>{const r=p.marks[s];return `<td title="${esc(r?.source||'')}">${r?.status==='OK'?`<span class="mark">${r.mark}</span> <span class="badge grade-badge grade-${esc(r.grade)}">${esc(r.grade)}</span>`:esc(r?.status||'—')}</td>`;}).join('')}<td><strong>${p.aCount}</strong></td><td><strong>${p.total}/${Object.keys(p.marks).length*100}</strong></td><td>${p.average===null?'—':p.average.toFixed(2)+'%'}</td></tr>`;if(hasPbd)html+=`<tr class="pbd-row">${hasMarks?'':rank+name}<td>${f.assessment==='COMBINED'?'PBD Akhir':esc(assessmentLabel(f.assessment))}</td>${currentSubjects.map(s=>`<td>${p.pbd[s]?`<span class="tp ${/^TP[12]$/.test(p.pbd[s].tp)?'low':''}">${esc(p.pbd[s].tp||p.pbd[s].status)}</span>`:'—'}</td>`).join('')}<td colspan="3">Penguasaan PBD</td></tr>`;return `<tbody class="student-result">${html}</tbody>`;}).join('')}</table></div>`;}
function multiResultsTable(list){
 const onlyPbd=list.every(p=>!Object.keys(p.marks).length);
 const chosen=selectedAssessments();const oldMode=f.assessment;
 const groups=list.map(p=>{
  let rows=[];
  for(const v of p.assessmentViews||[]){f.assessment=v.id;const html=resultsTable([{...v,assessmentViews:undefined}]);const body=html.match(/<tbody class="student-result">([\s\S]*?)<\/tbody>/)?.[1]||'';rows.push(...body.matchAll(/<tr[^>]*>[\s\S]*?<\/tr>/g));}
  const mid=p.assessmentViews?.find(v=>v.id==='PBD_MID');const end=p.assessmentViews?.find(v=>v.id==='PBD_END'||v.id==='COMBINED');
  const compare=chosen.includes('PBD_MID')&&(chosen.includes('PBD_END')||chosen.includes('COMBINED'));
  const count=rows.length+(compare?1:0);
  let body=rows.map((m,i)=>{let row=m[0].replace(/<td class="(?:rank|name)"[\s\S]*?<\/td>/g,'');if(i===0)row=row.replace(/(<tr[^>]*>)/,`$1<td class="rank" rowspan="${count}">${(f.sort==='subject'?p.subjectRank:p.rank)||'—'}</td><td class="name" rowspan="${count}"><button data-profile="${esc(p.key)}">${esc(p.name)}</button><small>${p.year} ${esc(p.className)}</small></td>`);return row;}).join('');
  if(compare)body+=`<tr class="progress-row"><td>Perubahan TP</td>${currentSubjects.map(sub=>{const a=mid?.pbd[sub]?.tp,b=end?.pbd[sub]?.tp;if(!/^TP[1-6]$/.test(a||'')||!/^TP[1-6]$/.test(b||''))return '<td>—</td>';const d=Number(b.slice(2))-Number(a.slice(2));return `<td class="${d>0?'progress-up':d<0?'progress-down':''}">${d>0?'Naik +'+d:d<0?'Turun '+d:'Kekal'}</td>`;}).join('')}<td colspan="3">Pertengahan → Akhir</td></tr>`;
  const label=p.pbdSummary?.counts.map((n,i)=>n?'TP'+(6-i)+': '+n:'').filter(Boolean).join(' · ')||'Belum ditaksir';
  if(onlyPbd){body=body.replace(/<td class="rank"[\s\S]*?<\/td>/,'');body=body.replace(/(<small>[\s\S]*?<\/small>)/,`$1<small class="tp-distribution">${esc(label)} · ${p.pbdSummary?.assessed||0} ditaksir</small>`);}
  return `<tbody class="student-result">${body}</tbody>`;
 });f.assessment=oldMode;
 let result=`<div class="table-scroll"><table class="results-table"><thead><tr><th class="rank">${f.sort==='subject'?'Kedudukan subjek':'Kedudukan'}</th><th class="name">Nama murid / Kelas</th><th>Pentaksiran</th>${currentSubjects.map(s=>`<th>${esc(s)}</th>`).join('')}<th>Bil. A</th><th>Jumlah</th><th>Purata</th></tr></thead>${groups.join('')}</table></div>`;if(onlyPbd)result=result.replace(/<th class="rank">[\s\S]*?<\/th>/,'').replace('class="results-table"','class="results-table pbd-only-table"').replace('<th>Bil. A</th><th>Jumlah</th><th>Purata</th>','<th colspan="3">Penguasaan PBD</th>');return result;
}
function studentsView(){title(pbdOnly()?'Penguasaan setiap murid.':'Keputusan setiap murid.','Tandakan pentaksiran untuk dibandingkan. Perubahan TP menunjukkan beza Pertengahan dengan Akhir.',pbdOnly()?'SENARAI & PENGUASAAN':'SENARAI & RANKING');$('#view').innerHTML=`${printTitle()}<section class="panel"><label class="screen-only">Cari nama murid<input id="search" type="search" placeholder="Taip nama murid…" value="${esc(search)}"></label>${toolbar()}<p class="hint">${pbdOnly()?'Susunan PBD tanpa nombor kedudukan: bilangan TP6, kemudian TP5 hingga TP1. Taburan sama diletakkan bersama, nama A–Z. Perbandingan diasingkan mengikut tahun dan kumpulan subjek yang sama; bilangan TP ditaksir ditunjukkan di bawah nama. Susunan TP menggunakan PBD Akhir apabila dipilih, selainnya Pertengahan. Rekod tiada tidak dianggap TP rendah.':'Kedudukan rasmi: bilangan A, kemudian jumlah. Jika beberapa pentaksiran dipilih, kedudukan utama mengikut UASA + MPT4 (gabungan), kemudian UASA atau MPT4 mengikut pilihan; markah pentaksiran berasingan tidak dijumlahkan. Ringkasan PBD menggunakan Akhir jika dipilih, selainnya Pertengahan. Seri berkongsi kedudukan (1, 1, 3). Dikira mengikut tahun dan kumpulan subjek sama; murid belum lengkap tidak diberi kedudukan. Pilihan markah subjek memaparkan kedudukan subjek; pilihan lain mengekalkan kedudukan keseluruhan.'}</p><div id="results">${resultsTable(people.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())))}</div></section>`;$('#search').oninput=e=>{search=e.target.value;$('#results').innerHTML=resultsTable(people.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())));};}
function analysisView(){title('Analisis yang boleh diteroka.','Pilih tahun, kelas atau subjek untuk melihat pecahan keputusan.','ANALISIS AKADEMIK');const m=metrics();const summary=currentSubjects.map(s=>{const marks=m.marks.filter(r=>r.subject===s);const tps=m.tp.filter(r=>r.subject===s);return `<tr><td class="name"><button data-subject="${esc(s)}">${esc(SUBJECTS[s]||s)}</button></td><td>${marks.length}</td><td>${marks.length?(marks.reduce((a,r)=>a+r.mark,0)/marks.length).toFixed(2):'—'}</td>${['A','B','C','D','E','F'].map(g=>`<td>${marks.filter(r=>r.grade===g).length}</td>`).join('')}${[1,2,3,4,5,6].map(n=>`<td>${tps.filter(r=>r.tp==='TP'+n).length}</td>`).join('')}</tr>`;}).join('');$('#view').innerHTML=`${printTitle()}<div class="kpi-grid">${kpi('Murid',people.length,'Dalam penapis semasa')}${kpi('Markah ditaksir',m.marks.length,'Rekod subjek')}${kpi('Rekod PBD',m.tp.length,'TP sah')}${kpi('Subjek',currentSubjects.length,'Dalam paparan')}</div><section class="panel"><div class="panel-head"><div><h3>Ringkasan subjek</h3><p>Bilangan gred dan TP, tanpa mencampurkan markah dengan TP.</p></div></div>${toolbar()}<div class="table-scroll"><table><thead><tr><th class="name">Subjek</th><th>Ditaksir</th><th>Purata</th>${['A','B','C','D','E','F','TP1','TP2','TP3','TP4','TP5','TP6'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${summary}</tbody></table></div></section><div class="two-col"><section class="panel"><h3>Perbandingan PBD Pertengahan / Akhir</h3><p class="hint">Murid dipadankan melalui ID yang sama dalam sesi ${esc(f.session)}.</p>${comparison()}</section><section class="panel"><h3>Status data mengikut kelas</h3>${classStatus()}</section></div>`;}
function comparison(){const rows=selectRows(state.records,f);return currentSubjects.map(sub=>{const mid=rows.filter(r=>r.subject===sub&&r.assessment==='PBD_MID'&&/^TP[1-6]$/.test(r.tp));const end=rows.filter(r=>r.subject===sub&&r.assessment==='PBD_END'&&/^TP[1-6]$/.test(r.tp));const m=new Map(mid.map(r=>[r.studentKey,r]));const pairs=end.filter(r=>m.has(r.studentKey));const up=pairs.filter(r=>Number(r.tp.slice(2))>Number(m.get(r.studentKey).tp.slice(2))).length;return `<div class="list-item"><strong>${esc(sub)}</strong><small> · ${pairs.length} pasangan murid</small><p>${pairs.length?`${up} meningkat · ${pairs.length-up} kekal / menurun`:'Belum ada kedua-dua pentaksiran untuk dibandingkan.'}</p></div>`;}).join('');}
function classStatus(){const groups=[...new Set(people.map(p=>p.year+' '+p.className))];return groups.map(k=>{const ps=people.filter(p=>p.year+' '+p.className===k);const n=ps.filter(p=>p.complete).length;return `<div class="list-item"><strong>${esc(k)}</strong><p>${ps.length} murid · ${n} keputusan markah lengkap</p></div>`;}).join('')||'<p class="hint">Tiada kelas.</p>';}
function profile(key){const p=people.find(x=>x.key===key);if(!p)return;const subs=[...new Set([...Object.keys(p.marks),...Object.keys(p.pbd)])];if(p.assessmentViews){modal('Profil pencapaian',`<button class="btn secondary no-print" data-action="slip">Cetak slip murid</button><h2>${esc(p.name)}</h2><p>${esc(assessmentName())} · ${esc(f.session)}</p>${resultsTable([p])}`);return;}modal('Profil pencapaian',`<button class="btn secondary no-print" data-action="slip">Cetak slip murid</button><h2>${esc(p.name)}</h2><p class="hint">${p.year} ${esc(p.className)} · Sesi ${esc(f.session)} · ${esc(assessmentName())}</p><div class="profile-grid">${kpi('Bilangan A',p.aCount,'UASA / MPT4')}${kpi('Jumlah',p.total,'Markah ditaksir')}${kpi('Purata',p.average?.toFixed(2)||'—','Peratus')}</div><div class="table-scroll"><table><thead><tr><th>Subjek</th><th>Markah</th><th>Gred</th><th>PBD</th></tr></thead><tbody>${subs.map(s=>`<tr><td>${esc(s)}</td><td>${p.marks[s]?.mark??esc(p.marks[s]?.status||'—')}</td><td>${p.marks[s]?.grade?`<span class="badge grade-badge grade-${esc(p.marks[s].grade)}">${esc(p.marks[s].grade)}</span>`:'—'}</td><td>${esc(p.pbd[s]?.tp||'—')}</td></tr>`).join('')}</tbody></table></div>${subs.filter(s=>p.pbd[s]?.comment||p.pbd[s]?.effort).map(s=>`<div class="list-item"><strong>${esc(SUBJECTS[s]||s)}</strong><p>${esc(p.pbd[s].comment)}</p><small>Usaha: ${esc(p.pbd[s].effort||'—')}</small></div>`).join('')}`);}
function interventionView(){title('Bimbingan dengan hala tuju.','Kenal pasti murid, rekod tindakan dan semak perkembangan.','INTERVENSI');const focus=people.filter(p=>Object.values(p.pbd).some(r=>(!f.subject||r.subject===f.subject)&&/^TP[12]$/.test(r.tp)));$('#view').innerHTML=`${printTitle()}<section class="panel"><div class="panel-head"><div><h3>Murid TP1 / TP2</h3><p>${focus.length} murid unik dalam penapis semasa.</p></div><button class="btn" data-action="teacher">${teacher?'Ruang kerja guru':'Log masuk guru'}</button></div>${focus.map(p=>`<div class="list-item"><button class="text-btn" data-profile="${esc(p.key)}">${esc(p.name)}</button><small> · ${p.year} ${esc(p.className)}</small><p>${Object.values(p.pbd).filter(r=>(!f.subject||r.subject===f.subject)&&/^TP[12]$/.test(r.tp)).map(r=>`<span class="badge red">${esc(r.subject)} ${esc(r.tp)}</span>`).join(' ')}</p></div>`).join('')||'<p class="hint">Tiada murid TP1 / TP2 dalam pilihan ini.</p>'}</section><section class="panel"><h3>Ruang kerja tindakan</h3><p class="hint">Akses guru menggunakan e-mel dan PIN sedia ada. Rekod kelompok, individu dan program panitia terus disimpan melalui Apps Script.</p><div class="actions"><button class="btn secondary" data-work="group">Intervensi kelompok</button><button class="btn secondary" data-work="individual">Intervensi individu</button><button class="btn secondary" data-work="program">Program panitia</button><button class="btn secondary" data-action="teacher">Status tindakan</button></div></section>`;}
function teacherLogin(){modal('Akses guru',`<form id="teacher-login" class="form-grid"><label class="full">E-mel DELIMa<input name="email" type="email" autocomplete="username" required></label><label class="full">PIN Guru<input name="password" type="password" autocomplete="current-password" required></label><button class="btn full">Masuk ruang kerja</button><p class="hint full" id="login-status"></p></form>`);$('#teacher-login').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const credentials={teacherEmail:fd.get('email'),teacherPin:fd.get('password')};await busy(e.target,async()=>{const data=await request('get_teacher_workspace',{session:f.session,...credentials});teacher={...credentials,data};showTeacherWorkspace();});};}
async function showTeacherWorkspace(){if(!teacher)return teacherLogin();try{teacher.data=await request('get_teacher_workspace',{session:f.session,teacherEmail:teacher.teacherEmail,teacherPin:teacher.teacherPin});}catch(e){toast(e.message);return;}const d=teacher.data;modal('Ruang kerja guru',`<p><strong>${esc(d.teacher.name)}</strong> · ${esc(d.teacher.role)}</p><div class="actions"><button class="btn secondary" data-work="group">Kelompok</button><button class="btn secondary" data-work="individual">Individu</button><button class="btn secondary" data-work="program">Program</button><button class="text-btn" data-action="teacher-out">Log keluar</button></div>${[...(d.groups||[]).map(r=>({...r,kind:'KELOMPOK'})),...(d.individuals||[]).map(r=>({...r,kind:'INDIVIDU'})),...(d.programs||[]).map(r=>({...r,kind:'PROGRAM'}))].map(r=>`<div class="list-item"><strong>${esc(r.groupName||r.studentName||r.programName)}</strong><p>${esc(r.subject)} · ${esc(r.status)}</p><p>${esc(r.interventionAction||r.activities||r.issue)}</p><button class="text-btn" data-monitor="${esc(r.id)}" data-kind="${r.kind}">Tambah pemantauan</button></div>`).join('')||'<p class="hint">Belum ada rekod tindakan untuk akaun ini.</p>'}`);}
function workForm(kind){if(!teacher)return teacherLogin();const ps=people.filter(p=>!f.year||p.year===Number(f.year));modal(kind==='program'?'Program panitia':kind==='group'?'Intervensi kelompok':'Intervensi individu',`<p class="hint">Pilih tahun, kelas dan subjek pada penapis utama sebelum merekod intervensi. Sesi ${esc(f.session)}.</p><form id="work-form" class="form-grid"><label>Subjek<select name="subject">${currentSubjects.map(s=>option(s,SUBJECTS[s]||s,f.subject)).join('')}</select></label>${kind==='program'?'<label>Nama program<input name="programName" required></label>':`<label>Tahun<input name="year" type="number" min="1" max="6" value="${esc(f.year||4)}" required></label><label>Kelas<select name="className">${[...new Set(ps.map(p=>p.className))].map(c=>option(c,c,f.className)).join('')}</select></label><label>TP asal<select name="originalTp">${[1,2,3,4,5,6].map(n=>option('TP'+n,'TP'+n,'TP2')).join('')}</select></label>${kind==='group'?'<label class="full">Nama kelompok<input name="groupName" required></label>':''}<fieldset class="full checklist"><legend>${kind==='group'?'Pilih murid (kelas dan tahun mesti sepadan)':'Pilih seorang murid'}</legend>${ps.map(p=>`<label><input type="${kind==='group'?'checkbox':'radio'}" name="member" value="${esc(p.key)}">${esc(p.name)} · ${p.year} ${esc(p.className)}</label>`).join('')}</fieldset>`}<label class="full">Isu / kemahiran<textarea name="issue" required></textarea></label><label class="full">Objektif<textarea name="objective" required></textarea></label><label class="full">Aktiviti / tindakan<textarea name="interventionAction" required></textarea></label><label>Tarikh mula<input type="date" name="startDate" required></label><label>Tarikh semakan<input type="date" name="reviewDate" required></label><label class="full">Sasaran / petunjuk kejayaan<input name="target" required></label><label>Status<select name="status"><option>DIRANCANG</option><option>SEDANG DILAKSANAKAN</option><option>SELESAI</option></select></label><button class="btn full">Simpan tindakan</button><p class="hint full" id="form-status"></p></form>`);$('#work-form').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{const fd=new FormData(e.target);const b=Object.fromEntries(fd);delete b.member;b.session=f.session;b.teacherEmail=teacher.teacherEmail;b.teacherPin=teacher.teacherPin;const selected=fd.getAll('member').map(key=>ps.find(p=>p.key===key));if(kind!=='program'){if(!selected.length)throw Error('Pilih murid dahulu.');if(selected.some(p=>p.year!==Number(b.year)||p.className!==b.className))throw Error('Murid pilihan mesti dalam tahun dan kelas yang dinyatakan.');if(kind==='group')b.members=selected.map(p=>({studentName:p.name,studentKey:p.key,tpBefore:p.pbd[b.subject]?.tp||b.originalTp}));else{b.studentName=selected[0].name;b.studentKey=selected[0].key;}}else{b.activities=b.interventionAction;b.successIndicator=b.target;b.endDate=b.reviewDate;b.targetGroup=f.year?'Tahun '+f.year:'Mengikut sasaran panitia';}await request({group:'save_group_intervention',individual:'save_individual_intervention',program:'save_panitia_program'}[kind],b);toast('Tindakan berjaya disimpan.');await showTeacherWorkspace();});};}
function monitorForm(id,kind){modal('Rekod pemantauan',`<form id="monitor-form" class="form-grid"><label class="full">Perkembangan<textarea name="progress" required></textarea></label><label class="full">Hasil / impak<textarea name="result"></textarea></label><label class="full">Tindakan seterusnya<textarea name="nextAction"></textarea></label><label>Semakan berikutnya<input type="date" name="nextReviewDate"></label><label>Status<select name="status"><option>SEDANG DILAKSANAKAN</option><option>SELESAI</option></select></label><button class="btn full">Simpan pemantauan</button><p class="hint full" id="form-status"></p></form>`);$('#monitor-form').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{await request('save_monitoring',{...Object.fromEntries(new FormData(e.target)),referenceType:kind,referenceId:id,teacherEmail:teacher.teacherEmail,teacherPin:teacher.teacherPin});toast('Pemantauan disimpan.');showTeacherWorkspace();});};}
function reportsView(){title('Laporan ikut keperluan guru.','Cetakan dan fail muat turun mengikuti penapis pilihan.','PUSAT LAPORAN');$('#view').innerHTML=`<section class="panel"><h3>Skop laporan</h3><p>${esc(assessmentName())} · ${esc($('#scope-label').textContent)}</p><p class="hint">Tetapkan skop di menu Murid atau Analisis. CSV boleh dibuka dalam Excel atau Google Sheets. Cetak / PDF menggunakan fungsi cetakan pelayar.</p><div class="actions"><button class="btn" data-action="report-students">Laporan keputusan murid</button><button class="btn secondary" data-action="report-analysis">Ringkasan subjek / panitia</button><button class="btn secondary" data-action="csv">Muat turun CSV</button></div><div class="notice">Untuk Tahun 4, pilih MPT4 sahaja bagi BM, BI, Matematik dan Sains; pilih UASA + MPT4 untuk laporan gabungan.</div></section>`;}
function dialogView(){title('Dialog prestasi, sedia dibentang.','Data mengikut penapis semasa; punca dan tindakan disemak oleh guru.','DIALOG PRESTASI');const m=metrics();const key='sap.dialog.'+f.session+'.'+selectedAssessments().join('-')+'.'+f.year+'.'+f.subject;let draft;try{draft=JSON.parse(localStorage.getItem(key)||'{}');}catch(e){draft={};}$('#view').innerHTML=`<div class="actions"><button class="btn" data-action="print">Cetak slaid / PDF</button><button class="btn secondary" id="export-pptx">Muat turun PowerPoint</button><span class="hint">Draf dialog disimpan pada peranti ini.</span></div><section class="slide"><p class="eyebrow">SK TEMIN · SESI ${esc(f.session)}</p><h2>Dialog Prestasi Akademik</h2><p>${esc(assessmentName())} · ${esc($('#scope-label').textContent)}</p><div class="kpi-grid">${kpi('Murid',people.length,'Dalam skop')}${kpi('Purata markah',m.avg?.toFixed(2)||'—','Rekod ditaksir')}${kpi('Penguasaan PBD',m.mastery===null?'—':m.mastery.toFixed(1)+'%','TP3–TP6')}${kpi('Fokus intervensi',m.focus,'Murid TP1/TP2')}</div></section><section class="slide"><h2>Dapatan utama</h2>${subjectBars(m.marks)}<p>TP1–TP2: ${m.tp.filter(r=>/^TP[12]$/.test(r.tp)).length} rekod daripada ${m.tp.length} rekod TP.</p></section><section class="slide"><h2>Analisis punca untuk disahkan</h2><p class="hint">Punca tidak boleh ditentukan daripada markah sahaja. Isi berdasarkan perbincangan dan evidens.</p><div class="fishbone">${['Murid','Guru','Kaedah PdP','Pentaksiran','Bahan & kemudahan','Persekitaran'].map((label,i)=>`<article><strong>${label}</strong><textarea data-draft="cause${i}" placeholder="Punca yang telah dikenal pasti…">${esc(draft['cause'+i]||'')}</textarea></article>`).join('')}</div></section><section class="slide"><h2>Pelan tindakan & impak</h2><div class="form-grid">${[['issue','Isu utama'],['action','Intervensi / tindakan'],['pic','Guru bertanggungjawab'],['period','Tempoh'],['target','Petunjuk kejayaan'],['impact','Impak selepas pelaksanaan']].map(([k,l])=>`<label>${l}<textarea data-draft="${k}">${esc(draft[k]||'')}</textarea></label>`).join('')}</div></section>`;document.querySelectorAll('[data-draft]').forEach(el=>el.oninput=()=>{draft[el.dataset.draft]=el.value;localStorage.setItem(key,JSON.stringify(draft));});$('#export-pptx').onclick=async()=>{try{await exportPowerPoint(m,draft);}catch(e){toast(e.message);}};}
async function exportPowerPoint(m,draft){if(!window.PptxGenJS)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/pptxgen.bundle.js';s.onload=resolve;s.onerror=()=>reject(Error('Fail PowerPoint tidak dapat dimuatkan.'));document.head.append(s);});const pptx=new window.PptxGenJS();pptx.layout='LAYOUT_WIDE';pptx.author='SK TEMIN';pptx.subject='Dialog Prestasi SAP-TEMIN';const add=(title,lines)=>{const slide=pptx.addSlide();slide.background={color:'F2F6F8'};slide.addText('SAP-TEMIN · SK TEMIN · '+f.session,{x:.6,y:.4,w:12,h:.3,fontSize:12,color:'007E7B'});slide.addText(title,{x:.6,y:1,w:12,h:.8,fontSize:30,bold:true,color:'133246'});slide.addText(lines.join('\n\n'),{x:.7,y:2,w:11.8,h:4.6,fontSize:19,color:'133246',breakLine:false,fit:'shrink'});};add('Dialog Prestasi Akademik',[assessmentName(),$('#scope-label').textContent,`${people.length} murid · Purata markah ${m.avg?.toFixed(2)||'—'} · Penguasaan PBD ${m.mastery?.toFixed(1)||'—'}%`]);add('Dapatan utama',currentSubjects.map(s=>{const r=m.marks.filter(r=>r.subject===s);return `${SUBJECTS[s]||s}: ${r.length?(r.reduce((a,v)=>a+v.mark,0)/r.length).toFixed(2):'—'} (${r.length} rekod markah)`;}));add('Analisis punca',['Murid','Guru','Kaedah PdP','Pentaksiran','Bahan & kemudahan','Persekitaran'].map((v,i)=>v+': '+(draft['cause'+i]||'Belum disahkan')));add('Pelan tindakan',[`Isu: ${draft.issue||'—'}`,`Tindakan: ${draft.action||'—'}`,`PIC: ${draft.pic||'—'} · Tempoh: ${draft.period||'—'}`,`Sasaran: ${draft.target||'—'}`,`Impak: ${draft.impact||'Belum dinilai'}`]);await pptx.writeFile({fileName:`SAP-TEMIN-Dialog-${f.session}.pptx`});}
function settingsView(){title('Sambungan pangkalan data.','Tetapan ini disimpan pada peranti yang digunakan.','TETAPAN');$('#view').innerHTML=`<section class="panel"><form id="settings-form"><label>URL Web App Apps Script v3<input name="url" type="url" value="${esc(apiUrl)}" placeholder="https://script.google.com/macros/s/…/exec" required></label><p class="hint">Gunakan deployment daripada fail server/Code.gs yang dibekalkan. Pangkalan data lama kekal; jalankan setupSAPTEMINv3 sekali sebelum menyambung.</p><div class="actions"><button class="btn">Simpan & sambung</button><button type="button" class="btn secondary" data-action="demo">Guna data contoh</button></div><p id="form-status" class="hint"></p></form></section>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();const url=String(new FormData(e.target).get('url')).trim();if(!/^https:\/\/script\.google\.com\/(?:a\/macros\/[A-Za-z0-9.-]+|macros)\/s\/[A-Za-z0-9_-]+\/exec$/.test(url)){toast('Gunakan URL Apps Script rasmi yang berakhir /exec.');return;}await busy(e.target,async()=>{const prior=apiUrl;apiUrl=url;try{const info=await request('manifest_v3');if(info.apiVersion!=='3.0.0'||!info.version)throw Error('Web App ini belum tersedia. Pasang kod v3 dan jalankan setupSAPTEMINv3 dahulu.');}catch(err){apiUrl=prior;throw err;}admin=null;teacher=null;localStorage.setItem('sap.v3.api',url);state={...state,records:[],version:'',demo:false,preview:false};originalOnline=null;initFilters();render();await sync(true);});};}
function helpView(){title('Panduan ringkas guru.','Teroka data dengan beberapa sentuhan.','PANDUAN');$('#view').innerHTML=`<section class="panel"><h2>Menu bawah sahaja</h2><p>Utama untuk ringkasan. Analisis untuk pecahan subjek dan kelas. Murid untuk keputusan dan ranking. Intervensi untuk tindakan susulan. Lagi untuk laporan dan tetapan.</p><h3>Keputusan Tahun 4</h3><p>UASA + MPT4 mengambil BM, BI, Matematik dan Sains daripada MPT4. Subjek lain daripada UASA. PBD Akhir dipaparkan berasingan pada baris bawah.</p><h3>Ranking</h3><p>Bilangan A terbanyak, kemudian jumlah tertinggi. Jika kedua-duanya sama, kedudukan bersama (1, 1, 3). Perbandingan dalam tahun dan kumpulan subjek yang sama sahaja. T / TD tidak dianggap sifar dan keputusan belum lengkap tidak diberi kedudukan.</p><h3>Untuk admin</h3><p>Tekan logo SK Temin tiga kali dalam masa singkat. Log masuk dengan e-mel ADMIN aktif dan PIN dalam AKSES_GURU. Pilih sesi dan pentaksiran, muat naik fail, semak pratonton, kemudian sahkan simpan.</p><h3>Fail yang disokong versi ini</h3><p>JSON classes/students/subjects seperti fail contoh PBD dan UASA yang dibekalkan. PDF MPT4 berteks dengan lajur JUMLAH daripada 50. PDF imbasan dan format Excel/CSV belum disokong dalam binaan ini.</p><h3>Data tahun lama</h3><p>Tambah sesi baharu tanpa reset. Kunci sesi lama sebagai arkib. Sandaran dibuat sebelum perubahan data v3; helaian dan rekod lama dikekalkan.</p></section>`;}
function adminLogin(){if(!apiUrl){toast('Tetapkan sambungan Apps Script v3 dahulu.');go('settings');return;}modal('Log masuk admin',`<form id="admin-login" class="form-grid"><label class="full">E-mel admin<input name="email" type="email" required autocomplete="username"></label><label class="full">Kata laluan / PIN admin<input name="password" type="password" required autocomplete="current-password"></label><button class="btn full">Log masuk</button><p class="hint full" id="login-status">Disahkan di pelayan. Sesi admin disimpan dalam memori sahaja.</p></form>`);$('#admin-login').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{const d=await request('v3_login',Object.fromEntries(new FormData(e.target)));admin={token:d.authToken,name:d.name};toast('Log masuk berjaya.');go('admin');});};}
function adminView(){if(!admin){go('home');adminLogin();return;}title('Pengurusan data sekolah.','Upload, sesi, pentaksiran dan sandaran dalam satu ruang.','ADMIN · '+admin.name);$('#view').innerHTML=`<section class="panel"><div class="panel-head"><h3>Upload data</h3><button class="btn secondary" data-action="admin-out">Log keluar</button></div>${uploadForm(true)}</section><section class="panel"><h3>Sesi persekolahan</h3><p class="hint">Sesi lama dikekalkan. Sesi dikunci masih boleh dilihat tetapi tidak boleh diimport.</p>${state.config.sessions.map(s=>`<div class="list-item"><strong>${esc(s.year)}</strong> <span class="badge ${s.locked?'warn':''}">${s.locked?'Arkib / dikunci':'Terbuka'}${state.config.activeSession===s.year?' · Sesi lalai':''}</span><div class="actions"><button class="btn secondary" data-lock="${s.year}" data-locked="${!s.locked}">${s.locked?'Buka kunci':'Kunci sesi'}</button><button class="text-btn" data-active="${s.year}">Jadikan sesi lalai</button></div></div>`).join('')}<form id="add-session" class="actions"><label>Sesi baharu<input name="year" type="number" min="2000" max="2099" value="${Number(state.config.activeSession)+1}" required></label><button class="btn">＋ Tambah sesi</button></form></section><section class="panel"><h3>Pentaksiran</h3><p class="hint">${state.config.assessments.map(a=>esc(a.name)+' ('+a.type+')').join(' · ')}</p><form id="add-assessment" class="form-grid"><label>Nama pentaksiran<input name="name" required></label><label>Jenis<select name="type"><option value="MARKAH">Markah</option><option value="TP">Tahap Penguasaan</option></select></label><button class="btn">＋ Tambah pentaksiran</button></form></section><section class="panel"><h3>Sandaran & pemulihan</h3><p class="hint">Sandaran automatik sebelum setiap import/perubahan. Pemulihan v3 tidak memadam atau menulis semula helaian PBD/intervensi lama.</p><div class="actions"><button class="btn" data-action="backup">Buat & muat turun sandaran</button><button class="btn secondary" data-action="backups">Senarai sandaran</button></div><label>Pulihkan fail sandaran v3<input type="file" id="restore-file" accept=".json,application/json"></label></section>`;bindUpload(true);$('#add-session').onsubmit=async e=>{e.preventDefault();await changeConfig({operation:'add_session',year:new FormData(e.target).get('year')});};$('#add-assessment').onsubmit=async e=>{e.preventDefault();await changeConfig({operation:'add_assessment',...Object.fromEntries(new FormData(e.target))});};$('#restore-file').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());confirmRestore({data:d});}catch(err){toast(err.message);}};}
function uploadForm(isAdmin){return `<form id="upload-form" class="form-grid"><label>Sesi<select name="session">${state.config.sessions.map(s=>option(s.year,s.year+(s.locked?' · Dikunci':''),state.config.activeSession)).join('')}</select></label><label>Pentaksiran<select name="assessment">${state.config.assessments.map(a=>option(a.id,a.name,'UASA')).join('')}</select></label><div class="upload-box full">${icon('upload')}<p>JSON PBD / UASA atau PDF MPT4</p><input name="files" type="file" accept=".json,.pdf,application/json,application/pdf" multiple required><p class="hint">Fail dibaca pada peranti. Hanya keputusan yang disahkan dihantar ketika Simpan.</p></div><button class="btn full">Baca & pratonton</button><p class="hint full" id="upload-status"></p></form><div id="import-preview"></div>`;}
function preview(){modal('Pratonton fail pada peranti',`<div class="notice warn">Mod pratonton sahaja. Tidak menghantar atau menyimpan data ke Google Sheets.</div>${uploadForm(false)}`);bindUpload(false);}
function bindUpload(isAdmin){$('#upload-form').onsubmit=async e=>{e.preventDefault();const form=e.target;await busy(form,async()=>{const fd=new FormData(form);const session=String(fd.get('session'));const a=state.config.assessments.find(a=>a.id===fd.get('assessment'));if(isAdmin&&state.config.sessions.find(s=>s.year===session)?.locked)throw Error('Sesi ini dikunci.');const files=fd.getAll('files');let rows=[];for(const file of files){if(file.size>30*1024*1024)throw Error('Fail melebihi 30 MB.');$('#upload-status').textContent='Membaca '+file.name+'…';if(file.name.toLowerCase().endsWith('.pdf')){if(a.id!=='MPT4')throw Error('Pilih pentaksiran MPT4 untuk fail PDF.');rows.push(...await parseMptPdf(file,session,msg=>$('#upload-status').textContent=msg));}else{const d=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(String(d.sessionYear)!==session)throw Error('Sesi dalam JSON tidak sama dengan sesi pilihan.');if(a.id==='UASA'&&!String(d.schema).includes('uasa'))throw Error('Fail bukan JSON UASA.');if(a.type==='TP'&&!String(d.schema).includes('pbd'))throw Error('Fail bukan JSON PBD.');if(a.id==='PBD_END'&&!String(d.schema).includes('akhir'))throw Error('Pilih pentaksiran yang sepadan dengan JSON.');if(a.id==='PBD_MID'&&String(d.schema).includes('akhir'))throw Error('Fail ini PBD Akhir, bukan Pertengahan.');rows.push(...await parseJson(d,a,session));}}const errors=validateRecords(rows);if(errors.length)throw Error(errors.slice(0,8).join('\n'));const existing=new Set(state.records.map(recordKey));const updated=rows.filter(r=>existing.has(recordKey(r))).length;const subjects=[...new Set(rows.map(r=>r.subject))];const classes=[...new Set(rows.map(r=>r.year+' '+r.className))];pending={rows,version:state.version,isAdmin};const missing=rows.filter(r=>r.status!=='OK').length;const unmapped=rows.filter(r=>r.assessment==='MPT4'&&!state.records.some(x=>x.studentKey===r.studentKey&&String(x.session)===session));$('#upload-status').textContent='Selesai membaca. Sila semak sebelum meneruskan.';$('#import-preview').innerHTML=`<div class="notice"><strong>${rows.length} rekod · ${new Set(rows.map(r=>r.studentKey)).size} murid · ${classes.length} kelas</strong><p>${esc(classes.join(', '))}<br>Subjek: ${esc(subjects.join(', '))}</p><p>${updated} padanan sedia ada akan dikemas kini; ${rows.length-updated} rekod baharu. Kelas dan pentaksiran lain dikekalkan.</p></div>${rows.some(r=>r.source.includes('Belum disahkan'))?'<div class="notice warn">PDF berstatus BELUM DISAHKAN. Pastikan fail ini versi yang mahu disimpan.</div>':''}${missing?`<div class="notice warn">${missing} rekod T / TD. Status ini tidak dikira sebagai sifar.</div>`:''}${unmapped.length?`<div class="notice warn">${unmapped.length} rekod MPT4 belum mempunyai padanan data pusat. Import UASA/PBD sesi sama dahulu atau semak ID.</div>`:''}<div class="table-scroll"><table><thead><tr><th>Nama</th><th>Kelas</th><th>Subjek</th><th>Keputusan</th></tr></thead><tbody>${rows.slice(0,30).map(r=>`<tr><td>${esc(r.name)}</td><td>${r.year} ${esc(r.className)}</td><td>${esc(r.subject)}</td><td>${esc(r.tp||(r.mark??r.status))} ${esc(r.grade||'')}</td></tr>`).join('')}</tbody></table></div><p class="hint">Pratonton 30 rekod pertama. ${a.id==='MPT4'?'JUMLAH /50 ×2 → /100. Gred mengikut skala UASA.':''}</p><div class="actions"><button class="btn" id="confirm-import">${isAdmin?'Sahkan simpan ke Google Sheets':'Gunakan dalam pratonton sahaja'}</button><button class="btn secondary" id="cancel-import">Batal</button></div>`;$('#confirm-import').onclick=confirmImport;$('#cancel-import').onclick=()=>{pending=null;$('#import-preview').innerHTML='';};});};}
async function confirmImport(){if(!pending)return;const btn=$('#confirm-import');btn.disabled=true;try{if(pending.isAdmin){if(!admin)throw Error('Sesi admin diperlukan.');const d=await request('v3_import',{authToken:admin.token,records:pending.rows,expectedVersion:pending.version});pending=null;await sync(true);toast(`${d.added} rekod ditambah, ${d.updated} dikemas kini.`);go('admin');}else{if(!originalOnline)originalOnline=state;const base=state.preview?state.records:state.demo?[]:state.records;state={...state,records:mergeRows(base,pending.rows),demo:true,preview:true};f.session=String(pending.rows[0].session);f.assessment=pending.rows[0].assessment;f.assessments=[f.assessment];pending=null;initFilters();go('students');status('PRATONTON PERANTI · Belum disimpan ke Google Sheets. Lagi → Sambungan untuk kembali ke data pusat.',true);}}catch(e){toast(e.message);btn.disabled=false;}}
async function changeConfig(body){try{await request('v3_config',{...body,authToken:admin.token,expectedVersion:state.version});await sync(true);go('admin');toast('Tetapan disimpan.');}catch(e){toast(e.message);}}
async function backup(){try{toast('Menyediakan sandaran…');const d=await request('v3_backup',{authToken:admin.token});download(`SAP-TEMIN-Sandaran-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(d.data,null,2),'application/json');toast('Sandaran disimpan di Drive dan dimuat turun.');}catch(e){toast(e.message);}}
async function backups(){try{const d=await request('v3_backups',{authToken:admin.token});modal('Sandaran tersedia',d.backups.map(b=>`<div class="list-item"><strong>${esc(b.kind)}</strong><p>${esc(formatDate(b.date))} · ${esc(b.note)}</p><button class="text-btn" data-restore="${esc(b.id)}">Pulihkan versi ini</button></div>`).join('')||'<p>Tiada sandaran.</p>');}catch(e){toast(e.message);}}
function confirmRestore(payload){modal('Sahkan pemulihan',`<div class="notice warn">Data dan konfigurasi v3 semasa akan diganti dengan sandaran pilihan. Sistem membuat sandaran keadaan semasa dahulu. Data PBD dan intervensi lama tidak ditulis semula.</div><form id="restore-confirm"><label>Taip PULIHKAN untuk mengesahkan<input name="confirm" required pattern="PULIHKAN"></label><div class="actions"><button class="btn danger">Pulihkan sandaran</button></div><p id="form-status" class="hint"></p></form>`);$('#restore-confirm').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{await request('v3_restore',{...payload,confirm:new FormData(e.target).get('confirm'),authToken:admin.token,expectedVersion:state.version});await sync(true);go('admin');toast('Pemulihan selesai.');});};}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function busy(form,fn){const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){const out=form.querySelector('#form-status,#login-status,#upload-status');if(out)out.textContent=e.message;toast(e.message);}finally{buttons.forEach(b=>b.disabled=false);}}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.go){if(el.dataset.go==='preview')preview();else go(el.dataset.go);}if(el.dataset.profile)profile(el.dataset.profile);if(el.dataset.subject){f.subject=el.dataset.subject;f.sort='subject';rebuildFilters();go('students');}if(el.dataset.tp){const tp=el.dataset.tp;const ps=people.filter(p=>Object.values(p.pbd).some(r=>r.tp===tp&&(!f.subject||r.subject===f.subject)));modal('Murid '+tp,ps.map(p=>`<div class="list-item"><button class="text-btn" data-profile="${esc(p.key)}">${esc(p.name)}</button><p>${p.year} ${esc(p.className)} · ${Object.values(p.pbd).filter(r=>r.tp===tp).map(r=>esc(r.subject)).join(', ')}</p></div>`).join('')||'<p>Tiada murid.</p>');}if(el.dataset.work)workForm(el.dataset.work);if(el.dataset.monitor)monitorForm(el.dataset.monitor,el.dataset.kind);if(el.dataset.lock)await changeConfig({operation:'lock_session',year:el.dataset.lock,locked:el.dataset.locked==='true'});if(el.dataset.active)await changeConfig({operation:'active_session',year:el.dataset.active});if(el.dataset.restore)confirmRestore({backupId:el.dataset.restore});switch(el.dataset.action){case'csv':download(`SAP-TEMIN-${f.session}-${f.assessment}.csv`,exportCsv(people.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())),currentSubjects,f.assessment,f.sort==='subject'?'subjectRank':'rank'),'text/csv;charset=utf-8');break;case'print':window.print();break;case'slip':printSlip();break;case'report-students':go('students');break;case'report-analysis':go('analysis');break;case'teacher':showTeacherWorkspace();break;case'teacher-out':teacher=null;sheet.close();toast('Guru telah log keluar.');break;case'admin-out':try{await request('v3_logout',{authToken:admin.token});}catch(e){}admin=null;go('home');break;case'backup':backup();break;case'backups':backups();break;case'demo':admin=null;teacher=null;state={...state,records:demoData(),demo:true,preview:false,version:''};initFilters();go('home');status('MOD CONTOH · Data rekaan sahaja.',true);break;}});
if(window.matchMedia('(max-width: 760px)').matches)$('#filters-box').open=false;
state.records=apiUrl?[]:demoData();state.demo=!apiUrl;initFilters();render();if(apiUrl){const old=await cached();if(old?.apiVersion==='3.0.0'){setData(old);status('Salinan terakhir · '+formatDate(old.version));}await sync();}else status('MOD CONTOH · Data rekaan untuk mencuba menu. Sambungan Google Sheets belum diaktifkan.',true);

function printSlip(){const content=$('#sheet-body').cloneNode(true);content.querySelectorAll('button').forEach(b=>b.remove());const out=document.createElement('section');out.id='slip-print';out.innerHTML='<h2>SK TEMIN · Slip Pencapaian Murid</h2>'+content.innerHTML;document.body.append(out);document.body.classList.add('printing-slip');const style=document.createElement('style');style.media='print';style.textContent='@page{size:A4 portrait;margin:15mm}';document.head.append(style);const cleanup=()=>{out.remove();style.remove();document.body.classList.remove('printing-slip');};window.addEventListener('afterprint',cleanup,{once:true});window.print();}
